SELECT ?point ?cls ?z ?lbl WHERE {
  ?point a ?cls .
  ?point brick:hasPropertyOf ?z .
  ?z rdfs:label ?lbl .
  FILTER(?lbl = "Perimeter_top_ZN_2" || ?lbl = "DataCenter_bot_ZN_6")
}

SELECT ?point ?cls ?z ?lbl WHERE {
  ?point a ?cls .
  FILTER(str(?cls) ENDS WITH "Air_Temperature_Sensor")
  ?point (brick:hasPropertyOf|brick:isPartOf) ?z .
  ?z rdfs:label ?lbl .
} LIMIT 40

